SELECT 'moj-all-verified-judgments-review-002-chunk-145' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"f21ad35d-c355-52b6-8a9d-fc5470e86204","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -أرض ومسايل -طلب رفع يد عن األرض -الدفع بوجود دعوى منظورة متعلقة بهذه الدعوى -احلكم بوقف النظر يف الدعوى تعليق ا حلن الفصل يف الدعوى األخرى.","document_number":"34303379","case_number":"34264825","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ضد","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/23","year":"1434","subject":"عقار -أرض ومسايل -طلب رفع يد عن األرض -الدفع بوجود دعوى منظورة متعلقة بهذه الدعوى -احلكم بوقف النظر يف الدعوى تعليق ا حلن الفصل يف الدعوى األخرى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/23 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34303379 :‬‬\n                         ‫َر ْق ُم الدعوى‪34264825 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34377673‬تاريخه‪1434/12/3 :‬هـ‬\n\n\n      ‫عقــار ‪ -‬أرض ومســايل ‪-‬طلــب رفــع يــد عــن األرض ‪ -‬الدفــع بوجــود‬\n      ‫دعــوى منظــورة متعلقــة بهــذه الدعــوى ‪ -‬احلكــم بوقــف النظــر يف‬\n                    ‫الدعــوى تعليق ـ ًا حلــن الفصــل يف الدعــوى األخــرى‪.‬‬\n\n\n\n\n                                                 ‫املادة ‪ 83‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه بــأن املدعــى عليــه اشــترى أرض ـ ًا مــن‬\n      ‫مخطــط وهــذه األرض تعــود مليكتهــا لــه وهــي مســيل حســب العبــارة‬\n      ‫التــي أمامهــا وتصــب يف مزارعــه شــرق اخلــط ويطلــب رفــع يــده عــن‬\n      ‫األرض واملســايل التــي تصــب يف مزرعتــه هكــذا ادعــى ‪ -‬أجــاب املدعى‬\n      ‫عليــه باملصادقــة علــى شــرائه األرض مــن املخطــط وأنكــر أن تكــون‬\n      ‫األرض ملــك للمدعــي ومســايل ملزرعتــه‪ ،‬واملدعــي ومعــه مجموعــة‬\n      ‫كبيــرة لديهــم دعــوى منظــورة يف الريــاض ضــد مالــك املخطــط الــذي‬\n      ‫باعــه والتــزال منظــورة بخصــوص ادعــاء ملكيــة األرض ‪ -‬صــادق‬\n      ‫املدعــي علــى إقامــة دعــوى يف محكمــة الريــاض ضــد مالــك املخطــط‬\n      ‫وأنــه مــن ضمــن املدعــن ‪ -‬ومبــا أن املدعــي صــادق علــى إقامــة دعــوى‬\n      ‫ضــد مالــك املخطــط الــذي بــاع علــى املدعــى عليــه بخصــوص ادعــاء‬\n\n‫‪299‬‬\n\f‫ملكيــة األرض وألنــه ال ميكــن البــت يف هــذه القضيــة حتــى تنتهــي‬\n‫الدعــوى القائمــة بالريــاض ألن هــذه الدعــوى ناشــئة عنهــا وإذا ثبتــت‬\n‫ملكيــة املدعــي لــأرض انتهــت هــذه الدعــوى ‪ -‬وبنــاء علــى املــادة ‪83‬‬\n‫مــن نظــام املرافعــات الشــرعية (إذا رأت احملكمــة تعليــق حكمهــا يف‬\n‫موضــوع الدعــوى علــى الفصــل يف مســألة أخــرى يتوقــف عليــه احلكــم‬\n‫فتأمــر بوقــف الدعــوى ‪ - )..‬ملــا تقــدم صــدر احلكــم بوقــف الدعــوى‬\n‫حتــى انتهــاء الدعــوى املقامــة مبحكمــة الريــاض العامــة ‪ -‬قنــع املدعــى‬\n‫عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n                ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة عســير‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف محكمــة محافظــة‬\n‫أحــد رفيــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس محكمــة‬\n‫محافظــة أحــد رفيــدة برقــم ‪ 34264825‬وتاريــخ ‪1434/06/10‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341392487‬وتاريــخ ‪1434/06/10‬ه ـ ففــي‬\n‫يــوم الســبت املوافق‪1434/08/13‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n‫وفيهــا حضــر ‪.....‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n‫وحضــر حلضــوره املدعــى عليــه ‪.....‬ســعودي بالســجل املدنــي رقــم ‪.....‬‬\n‫وبســؤال املدعــي عــن دعــواه قــال إن املدعــى عليــه اشــترى أرض مــن‬\n‫مخطــط ‪.....‬وشــريكه ‪ .....‬وهــذه األرض تعــود ملكيتهــا يف األســاس‬\n‫لــي وهــي مســيلة حســب العبــارة التــى أمامهــا وتصــب يف مزارعــي شــرق‬\n‫اخلــط حســب الوثائــق وصــورة الصــك املرفــق أطلــب رفــع يــد املدعــى‬\n\n                                                                                     ‫‪300‬‬\n\f      ‫عليــه عــن أرضــي ومســايلي التــي تصــب يف مزرعتــي هــذه دعــواي‬\n      ‫وبعــرض دعــوى املدعــي علــى املدعــى عليــه قــال مــا ذكــره املدعــي يف‬\n      ‫دعــواه مــن أننــي اشــتريت القطعــة رقــم ســبعني يف مخطط‪.....‬برقــم ‪/5‬أ‬\n      ‫‪/‬ع غــرب ‪ ...‬بأحــد رفيــدة كلــه صحيــح وأمــا مــا ذكــره مــن أن األرض‬\n      ‫ملــك لــه ومســايل ملزرعتــه كلــه غيــر صحيــح جملــة وتفصيــا فــاألرض‬\n      ‫مملوكــة لــي مبوجــب الصــك رقــم ‪ 2/126/8‬وتاريــخ ‪1433/11/9‬ه ـ‬\n      ‫والصــادر مــن كتابــة عــدل ‪ ....‬واملدعــي ومعــه مجموعــة كبيــرة مــن‬\n      ‫أهالــي ‪ ....‬لهــم دعــوى علــى مالــك املخطــط الــذي باعنــي ‪.....‬وال تــزال‬\n      ‫قائمــة بخصــوص ادعــاء ملكيــة األرض هكــذا أجــاب وبعــرض ذلــك‬\n      ‫علــى املدعــي قــال نعــم توجــد دعــوى قائمــة باحملكمــة العامــة بالريــاض‬\n      ‫ضــد ‪.....‬وأنــا مــن ضمــن املدعــن وهــي ال تــزال قائمــة بخصــوص ادعــاء‬\n      ‫ملكيتنــا لــأرض هكــذا أجــاب ورفعــت اجللســة النتهــاء وقتهــا حتــى‬\n      ‫يــوم الثالثــاء املوافــق ‪1434/8/23‬ه ـ الســاعة الثامنــة صباحا ويف جلســة‬\n      ‫أخــرى يــوم الثالثــاء املوافق‪1434/08/23‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الثامنــة صباحــا وفيهــا ‪.....‬وبســؤالهما هــل لديكــم ماتضيفونــه يف هــذه‬\n      ‫اجللســة قــاال ليــس لدينــا مانضيفــه ســوى ماذكرنــاه يف اجللســة املاضيــة‬\n      ‫هكــذا أجابــا فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة وملصادقــة‬\n      ‫املدعــي علــى أن لديــه دعــوى قائمــة يف احملكمــة العامــة بالريــاض‬\n      ‫ضــد مالــك املخطــط الــذي بــاع املدعــى عليــه بخصــوص ادعــاء ملكيــة‬\n      ‫األرض وألنــه الميكــن البــت يف هــذه القضيــة حتــى تنتهــي الدعــوى‬\n      ‫القائمــة بالريــاض ألن هــذه الدعــوى ناشــئة عنهــا وإذا ثبتــت ملكيــة‬\n      ‫املدعــي لــأرض انتهــت هــذه الدعــوى وقــد نصت املــادة الثالثــة والثمانون‬\n      ‫مــن نظــام املرافعــات الشــرعية ( إذا رأت احملكمــة تعليــق حكمهــا يف‬\n\n\n‫‪301‬‬\n\f‫موضــوع الدعــوى علــى الفصــل يف مســألة أخــرى يتوقــف عليهــا احلكــم‬\n‫فتأمــر بوقــف الدعــوى ومبجــرد زوال ســبب التوقــف يكــون للخصــوم‬\n‫طلــب الســير يف الدعــوى ) لــذا فقــد أمــرت بوقــف هــذه الدعــوى حتــى‬\n‫انتهــاء الدعــوى القائمــة باحملكمــة العامــة بالريــاض بخصــوص ادعــاء‬\n‫املدعــي ملكيــة األرض وبعــرض ذلــك علــى املدعــى عليــه قــرر القناعــة‬\n‫وقــرر املدعــي عــدم القناعــة وجــرى تســليمه نســخة مــن القــرار الشــرعي‬\n‫وذلــك لتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ اليــوم‬\n‫وإذا لــم يقــدم الالئحــة ســقط حقــه يف االســتئناف واكتســب احلكــم‬\n‫القطعيــة ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/08/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة الثالثــة‬\n‫مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بأحــد رفيــدة برقــم ‪ 341392487‬وتاريــخ‬\n‫‪1434/9/15‬ه ـ اخلاصــة بدعــوى‪ /‬أ‪ .....‬ضــد‪..... /‬بشــأن أرض املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪..... /‬برقــم ‪ 34303379‬وتاريــخ‬\n‫‪1434/8/23‬ه ـ املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملةلــم يظهــر مــا يوجــب االعتــراض لــذا قررنــا املوافقــة علــى احلكــم‬\n‫بوقــف الدعــوى‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪302‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                       ‫التصنيف‬      ‫م‬\n\n\n                                                         ‫تعويض عن‬\n  ‫‪5‬‬      ‫املطالبة بالتعويض عن سجن لقاء دعوى كيدية‬                     ‫‪1‬‬\n                                                          ‫السجن‬\n\n\n            ‫امتناع وكيل املدعي من حترير الدعوى‬\n  ‫‪11‬‬     ‫واالكتفاء بالئحة اعتراضية من حكم سابق‬           ‫حترير دعوى‬   ‫‪2‬‬\n             ‫(منقوض) ورد الدعوى (صرف نظر)‬\n\n\n          ‫صرف النظر عن الدعوى كونها غير محررة‬\n                                                         ‫صرف النظر‬\n  ‫‪15‬‬     ‫وإفهام املدعي بأن له احلق يف تقدمي الدعوى بعد‬                ‫‪3‬‬\n                                                          ‫عن دعوى‬\n                           ‫حتريرها‬\n\n\n         ‫صرف النظر عن مطالبة املدعي للمدعى عليه‬          ‫صرف النظر‬\n  ‫‪19‬‬                                                                  ‫‪4‬‬\n             ‫بنصيبه من اإلرث لعدم حترير الدعوى‬            ‫عن دعوى‬\n\n\n          ‫صرف النظر عن دعوى املدعي ضد املدعى‬\n  ‫‪23‬‬     ‫عليه يف قضية رفع مساحي ألرض المتناعه عن‬         ‫صرف نظر‬      ‫‪5‬‬\n                       ‫حترير دعواه‬\n\n\n         ‫صرف النظر عن دعوى املدعي لعدم اختصاص‬\n  ‫‪31‬‬                                                      ‫اختصاص‬      ‫‪6‬‬\n                      ‫احملكمة‬\n\n\n          ‫عدم قبول الدعوى لعدم االختصاص وإفهام‬\n  ‫‪39‬‬     ‫املدعي بأن له احلق يف إقامة الدعوى لدى اجلهة‬     ‫اختصاص‬      ‫‪7‬‬\n                          ‫املختصة‬\n\f‫الصفحة‬                     ‫املوضوع‬                       ‫التصنيف‬        ‫م‬\n\n\n            ‫احلكم بصرف النظر عن الدعوى لعدم‬\n  ‫‪46‬‬     ‫اختصاص احملكمة يف نظر النزاعات الناشئة‬          ‫اختصاص‬         ‫‪8‬‬\n                     ‫عن توزيع األراضي‬\n\n\n         ‫عدم اختصاص احملكمة بقضايا االعتداء على‬\n  ‫‪52‬‬     ‫رجل األمن أثناء عمله وإفهام املدعي أن ذلك من‬    ‫اختصاص‬         ‫‪9‬‬\n                   ‫اختصاص ديوان املظالم‬\n\n\n           ‫صرف النظر عن الدعوى لعدم االختصاص‬\n  ‫‪58‬‬                                                     ‫اختصاص‬         ‫‪10‬‬\n                         ‫النوعي‬\n\n\n            ‫صرف النظر